	@Inject
	public MncGrammarAccess(GrammarProvider grammarProvider,
			DmlGrammarAccess gaDml,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaDml = gaDml;
		this.gaTerminals = gaTerminals;
		this.pModel = new ModelElements();
		this.pImport = new ImportElements();
		this.pQualifiedNameWithWildCard = new QualifiedNameWithWildCardElements();
		this.pCommand = new CommandElements();
		this.pEvent = new EventElements();
		this.pResponse = new ResponseElements();
		this.pAlarm = new AlarmElements();
		this.pDataPoint = new DataPointElements();
		this.pOperatingStateUtility = new OperatingStateUtilityElements();
		this.pOperatingState = new OperatingStateElements();
		this.pSubscribableItemList = new SubscribableItemListElements();
		this.pAction = new ActionElements();
		this.pActionCommand = new ActionCommandElements();
		this.pActionAlarm = new ActionAlarmElements();
		this.pActionEvent = new ActionEventElements();
		this.pActionDataPoint = new ActionDataPointElements();
		this.pActionOperation = new ActionOperationElements();
		this.pActionParemeter = new ActionParemeterElements();
		this.pInterfaceDescription = new InterfaceDescriptionElements();
		this.pControlNode = new ControlNodeElements();
		this.pCommandResponseBlock = new CommandResponseBlockElements();
		this.pResponseBlock = new ResponseBlockElements();
		this.pResponseAggregationRule = new ResponseAggregationRuleElements();
		this.pBooleanOps = new BooleanOpsElements();
		this.pCheckParameterCondition = new CheckParameterConditionElements();
		this.pValidation = new ValidationElements();
		this.pTransition = new TransitionElements();
		this.pParameterTranslation = new ParameterTranslationElements();
		this.pEventBlock = new EventBlockElements();
		this.pAlarmBlock = new AlarmBlockElements();
		this.pDataPointBlock = new DataPointBlockElements();
		this.pAddress = new AddressElements();
		this.tADDRESSFORMAT = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "com.mncml.dsl.Mnc.ADDRESSFORMAT");
		this.pPort = new PortElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("com.mncml.dsl.Mnc".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
